DECLARE @ID_e9dcd487 UNIQUEIDENTIFIER,
@Name_e9dcd487 NVARCHAR(255),
@CategoryID_e9dcd487 UNIQUEIDENTIFIER,
@UserQuestion_e9dcd487 NVARCHAR(MAX),
@Description_e9dcd487 NVARCHAR(MAX),
@SQL_e9dcd487 NVARCHAR(MAX),
@TechnicalDescription_e9dcd487 NVARCHAR(MAX),
@OriginalSQL_e9dcd487 NVARCHAR(MAX),
@Feedback_e9dcd487 NVARCHAR(MAX),
@Status_e9dcd487 NVARCHAR(15),
@QualityRank_e9dcd487 INT,
@ExecutionCostRank_e9dcd487 INT,
@UsesTemplate_e9dcd487 BIT,
@AuditQueryRuns_e9dcd487 BIT,
@CacheEnabled_e9dcd487 BIT,
@CacheTTLMinutes_e9dcd487 INT,
@CacheMaxSize_e9dcd487 INT,
@EmbeddingVector_e9dcd487 NVARCHAR(MAX),
