DECLARE @ID_e1aa032a UNIQUEIDENTIFIER,
@Name_e1aa032a NVARCHAR(255),
@CategoryID_e1aa032a UNIQUEIDENTIFIER,
@UserQuestion_e1aa032a NVARCHAR(MAX),
@Description_e1aa032a NVARCHAR(MAX),
@SQL_e1aa032a NVARCHAR(MAX),
@TechnicalDescription_e1aa032a NVARCHAR(MAX),
@OriginalSQL_e1aa032a NVARCHAR(MAX),
@Feedback_e1aa032a NVARCHAR(MAX),
@Status_e1aa032a NVARCHAR(15),
@QualityRank_e1aa032a INT,
@ExecutionCostRank_e1aa032a INT,
@UsesTemplate_e1aa032a BIT,
@AuditQueryRuns_e1aa032a BIT,
@CacheEnabled_e1aa032a BIT,
@CacheTTLMinutes_e1aa032a INT,
@CacheMaxSize_e1aa032a INT,
@EmbeddingVector_e1aa032a NVARCHAR(MAX),
@EmbeddingModelID_e1aa032a UNIQUEIDENTIFIER,
@CacheValidationSQL_e1aa032a NVARCHAR(MAX),
@SQLDialectID_e1aa032a UNIQUEIDENTIFIER,
@Reusable_e1aa032a BIT,
@ExternalDataSourceID_e1aa032a UNIQUEIDENTIFIER,
@IsMaterialized_e1aa032a BIT
SET
  @ID_e1aa032a = '5A1E5000-0001-4000-A000-00000000000B'
SET
  @Name_e1aa032a = N'Sales: Deal Type Mix'
SET
  @CategoryID_e1aa032a = '5A1E5000-0000-4000-A000-000000000001'
SET
  @UserQuestion_e1aa032a = N'How is our business split between new, renewal and expansion motions?'
SET
  @Description_e1aa032a = N'Mix by DealType (master plan §9.3 measure 10). Reads the type TABLE, not type names: rows group by DealTypeID and render the name for display only, so a deployment that adds a fourth motion or renames one gets a correct extra row rather than a miscounted one.'
SET
  @SQL_e1aa032a = N'-- New vs renewal vs expansion mix. Master plan §9.3, measure 10 — via the DealType dimension (§9.2).
--
-- THE MIX IS READ FROM THE TYPE TABLE, NOT FROM TYPE NAMES. §9.3 phrases this measure as "new vs
-- renewal vs expansion", which are the labels the seeded rows happen to carry — but nothing here
-- compares them. Rows group by `DealTypeID` and render `DealType.Name` for display only, so a
-- deployment that adds a fourth motion, or renames "Expansion" to "Upsell", gets a correct extra row
-- rather than a silently miscounted one.
--
-- `RequiresRenewalSource` IS THE ONE FLAG THIS QUERY BRANCHES ON, and it is the same flag
-- `CloseDealOperation` uses to decide whether a close takes the renewal door. Reporting it here means
-- the mix and the routing agree by construction: a type the engine treats as a renewal is a type this
-- report counts as one.
--
-- DATE DIMENSION: ActualCloseDate for closed deals, ExpectedCloseDate for open ones — the mix
-- question is "what are we selling in this period", and an open deal belongs to the period it is
-- expected to land in. Both are reported separately below so the two are never silently added.
SELECT
    d.DealTypeID,
    dt.Name                                     AS DealTypeName,
    dt.RequiresRenewalSource,
    d.CompanyID,
    d.Company                                   AS CompanyName,
    d.PipelineID,
    d.Pipeline                                  AS PipelineName,
    SUM(CASE WHEN st.IsWon = 1 THEN 1 ELSE 0 END)                    AS WonCount,
    SUM(CASE WHEN st.IsWon = 1 THEN ISNULL(d.Amount, 0) ELSE 0 END)  AS WonAmount,
    SUM(CASE WHEN st.IsOpen = 1 THEN 1 ELSE 0 END)                   AS OpenCount,
    SUM(CASE WHEN st.IsOpen = 1 THEN ISNULL(d.Amount, 0) ELSE 0 END) AS OpenAmount,
    SUM(CASE WHEN st.IsLost = 1 THEN 1 ELSE 0 END)                   AS LostCount,
    -- A renewal deal that names no source contract is a data gap worth seeing rather than a row to
    -- filter out: it means the routing had nothing to renew against.
    SUM(CASE WHEN dt.RequiresRenewalSource = 1 AND d.RenewsContractID IS NULL THEN 1 ELSE 0 END)
                                                AS RenewalsMissingSource
FROM [__mj_BizAppsSales].vwDeals d
INNER JOIN [__mj_BizAppsSales].DealStatusType st
        ON st.ID = d.DealStatusTypeID
INNER JOIN [__mj_BizAppsSales].DealType dt
        ON dt.ID = d.DealTypeID
WHERE 1 = 1
  {% if CompanyID %}
  AND d.CompanyID = {{ CompanyID | sqlString }}
  {% endif %}
  {% if PipelineID %}
  AND d.PipelineID = {{ PipelineID | sqlString }}
  {% endif %}
  {% if PeriodStart %}
  AND COALESCE(d.ActualCloseDate, d.ExpectedCloseDate) >= {{ PeriodStart | sqlString }}
  {% endif %}
  {% if PeriodEnd %}
  AND COALESCE(d.ActualCloseDate, d.ExpectedCloseDate) <= {{ PeriodEnd | sqlString }}
  {% endif %}
GROUP BY
    d.DealTypeID, dt.Name, dt.RequiresRenewalSource,
    d.CompanyID, d.Company, d.PipelineID, d.Pipeline
ORDER BY
    WonAmount DESC;
'
SET
  @TechnicalDescription_e1aa032a = N'Grain: Deal. RequiresRenewalSource is the one flag this branches on, and it is the same flag CloseDealOperation uses to route a renewal — so the mix and the routing agree by construction. RenewalsMissingSource surfaces renewal-type deals with no RenewsContractID, which means the routing had nothing to renew against. Dates: actual close for closed deals, expected for open, reported in separate columns so the two are never added.'
SET
  @Status_e1aa032a = N'Approved'
SET
  @QualityRank_e1aa032a = 7
SET
  @ExecutionCostRank_e1aa032a = 2
SET
  @UsesTemplate_e1aa032a = 1
SET
  @AuditQueryRuns_e1aa032a = 0
SET
  @CacheEnabled_e1aa032a = 0
